#!/bin/bash
#flux: --job-name="{{ job_name }}"
# Translates directly from LSF -J

#flux: --queue={{ job_queue }}
# Translates directly from LSF -q

# LSF -o and -e being set to the same file is equivalent to merging them.
# Flux merges stdout and stderr by default when only --output is specified.
# Note: The templated timestamp `{{ current }}` cannot be replicated here.
#flux: --output="{{ job_name }}.out"

{% if run_time %}
#flux: -t {% format_lsf_walltime run_time %}
# Translates from LSF -W
{% endif %}

# Resource requests are translated below.
# The total number of nodes and tasks are specified for the job.
#flux: -N {{ nodes|default:1 }}
#flux: -n {{ nodes|default:1|multi:cores_per_node|default:1 }}

{% if ram_size %}
# LSF 'rusage[mem=...]' requests memory per-task/process.
#flux: --mem-per-task={{ ram_size }}M
{% endif %}

{% if gpu_per_node or use_gpu %}
# LSF '-gpu num=X' requests X GPUs per node. This is translated to a request
# for a total number of GPUs for the job, which Flux will distribute across the allocated nodes.
# The LSF 'j_exclusive=yes' option is the default behavior for GPU scheduling in Flux.
#flux: --gpus={{ nodes|default:1|multi:gpu_per_node|default:1 }}
{% endif %}

# The LSF directive '-cwd' sets the working directory. This is handled
# in the script body by manually changing to the desired directory.
cd {{ job_workspace }}

# The LSF job ID variable $LSB_JOBID is replaced with the Flux equivalent, $FLUX_JOB_ID.
ENV_JOB_ID=$FLUX_JOB_ID

